   $('.authorNoteCancel',listBox).forEach(button=>button.onclick=()=>{const card=button.closest('.authorNoteItem');$('.authorNoteEditForm',card).hidden=true;$('.authorNoteActions',card).hidden=false});
   $('.authorNoteEditForm',listBox).forEach(form=>form.onsubmit=async event=>{event.preventDefault();const card=form.closest('.authorNoteItem'),id=Number(card.dataset.noteId),textarea=$('textarea',form),save=$('.authorNoteSave',form),note=textarea.value;save.disabled=true;try{await api('/api/author/notes/'+id,{method:'PATCH',body:JSON.stringify({note})});setNotice('Private note updated.');await loadAuthorNotes()}catch(error){setNotice(error.message||'Could not update note.',true)}finally{save.disabled=false}});
